// Function to attach submenu click handlers
function attachSubmenuClickHandlers(previewDoc) {
    // Find all submenu items within dropdowns (desktop menu)
    const submenuItems = previewDoc.querySelectorAll('.menu-dropdown-content a');
    console.log('[DEBUG] Found desktop submenu items:', submenuItems.length);
    
    // Also find drawer submenu items (mobile menu)
    const drawerSubmenuItems = previewDoc.querySelectorAll('.drawer-dropdown-submenu-item');
    console.log('[DEBUG] Found drawer submenu items:', drawerSubmenuItems.length);
    
    // Combine both selections
    const allSubmenuItems = [...submenuItems, ...drawerSubmenuItems];
    
    allSubmenuItems.forEach(item => {
        item.addEventListener('click', function(e) {
            // Stop propagation to prevent parent's preventDefault
            e.stopPropagation();
            console.log('[DEBUG] Submenu item clicked, navigating to:', this.href);
            
            // Check if we're in the website builder editor context
            const href = this.getAttribute('href');
            if (href && window.parent && window.parent !== window) {
                // We're in the iframe, check if this is a special route
                if (href === '/collections' || href === '/cart' || href.startsWith('/products/')) {
                    e.preventDefault();
                    console.log('[DEBUG] Special route detected, handling navigation');
                    
                    // Navigate the parent window's iframe to the full preview URL
                    const previewIframe = window.parent.document.getElementById('preview-iframe');
                    if (previewIframe) {
                        // Use the Preview action with the appropriate page parameter
                        let previewUrl = '/WebsiteBuilder/Preview';
                        if (href === '/collections') {
                            previewUrl += '?page=collections';
                        } else if (href === '/cart') {
                            previewUrl += '?page=cart';
                        } else if (href.startsWith('/products/')) {
                            const handle = href.replace('/products/', '');
                            previewUrl += `?page=product&handle=${handle}`;
                        }
                        
                        console.log('[DEBUG] Navigating iframe to:', previewUrl);
                        previewIframe.src = previewUrl;
                    }
                    return;
                }
            }
            
            // For other links, let the navigation happen naturally
        });
    });
}

// Function to attach dropdown menu event listeners
function attachDropdownMenuListeners(previewDoc) {
    const menuItems = previewDoc.querySelectorAll('.menu-item-parent');
    console.log('[DEBUG] Found menu items with dropdowns:', menuItems.length);
    
    menuItems.forEach(item => {
        const dropdownId = item.getAttribute('data-dropdown');
        const dropdown = previewDoc.getElementById(dropdownId);
        const isHoverEnabled = item.getAttribute('data-hover') === 'true';
        
        console.log('[DEBUG] Processing menu item:', {
            label: item.textContent.trim(),
            dropdownId: dropdownId,
            dropdownFound: !!dropdown,
            isHoverEnabled: isHoverEnabled
        });
        
        if (!dropdown) {
            console.warn('[DEBUG] Dropdown not found for ID:', dropdownId);
            return;
        }
        
        if (isHoverEnabled) {
            // Hover behavior
            let hoverTimeout;
            
            item.addEventListener('mouseenter', function() {
                clearTimeout(hoverTimeout);
                console.log('[DEBUG] Mouse entered menu item, showing dropdown');
                dropdown.style.display = 'block';
                dropdown.style.opacity = '1';
                dropdown.style.visibility = 'visible';
                // Rotate dropdown indicator
                const indicator = item.querySelector('.dropdown-indicator');
                if (indicator) indicator.style.transform = 'rotate(180deg)';
            });
            
            item.addEventListener('mouseleave', function() {
                hoverTimeout = setTimeout(() => {
                    dropdown.style.display = 'none';
                    // Reset dropdown indicator
                    const indicator = item.querySelector('.dropdown-indicator');
                    if (indicator) indicator.style.transform = 'rotate(0deg)';
                }, 200);
            });
            
            dropdown.addEventListener('mouseenter', function() {
                clearTimeout(hoverTimeout);
            });
            
            dropdown.addEventListener('mouseleave', function() {
                dropdown.style.display = 'none';
                // Reset dropdown indicator
                const indicator = item.querySelector('.dropdown-indicator');
                if (indicator) indicator.style.transform = 'rotate(0deg)';
            });
        } else {
            // Click behavior
            item.addEventListener('click', function(e) {
                e.preventDefault();
                console.log('[DEBUG] Menu item clicked');
                const isOpen = dropdown.style.display === 'block';
                
                // Close all other dropdowns and reset their indicators
                previewDoc.querySelectorAll('.menu-dropdown-content').forEach(d => {
                    if (d !== dropdown) {
                        d.style.display = 'none';
                        const parentItem = previewDoc.querySelector(`[data-dropdown="${d.id}"]`);
                        if (parentItem) {
                            const ind = parentItem.querySelector('.dropdown-indicator');
                            if (ind) ind.style.transform = 'rotate(0deg)';
                        }
                    }
                });
                
                // Toggle current dropdown
                dropdown.style.display = isOpen ? 'none' : 'block';
                dropdown.style.opacity = isOpen ? '0' : '1';
                dropdown.style.visibility = isOpen ? 'hidden' : 'visible';
                console.log('[DEBUG] Dropdown toggled:', {isOpen: !isOpen, dropdownId: dropdownId});
                
                // Rotate dropdown indicator
                const indicator = item.querySelector('.dropdown-indicator');
                if (indicator) {
                    indicator.style.transform = isOpen ? 'rotate(0deg)' : 'rotate(180deg)';
                }
            });
            
            // Close dropdown when clicking outside
            previewDoc.addEventListener('click', function(e) {
                if (!item.contains(e.target) && !dropdown.contains(e.target)) {
                    dropdown.style.display = 'none';
                }
            });
        }
    });
}

// Function to load Google Fonts in the preview iframe
function loadFontsInPreview() {
    const previewFrame = document.getElementById('preview-iframe');
    if (!previewFrame || !previewFrame.contentDocument) return;
    
    const iframeHead = previewFrame.contentDocument.head;
    
    // Get all fonts from typography settings
    if (currentGlobalThemeSettings && currentGlobalThemeSettings.typography) {
        const typography = currentGlobalThemeSettings.typography;
        const fontsToLoad = new Set();
        
        // Collect all unique fonts
        if (typography.heading?.font) fontsToLoad.add(typography.heading.font);
        if (typography.body?.font) fontsToLoad.add(typography.body.font);
        if (typography.menu?.font) fontsToLoad.add(typography.menu.font);
        if (typography.product?.font) fontsToLoad.add(typography.product.font);
        if (typography.buttons?.font) fontsToLoad.add(typography.buttons.font);
        
        // Load each font
        fontsToLoad.forEach(fontValue => {
            const fontName = window.getFontNameFromValue ? window.getFontNameFromValue(fontValue) : null;
            if (fontName) {
                const linkId = `google-font-${fontValue}`;
                const existingLink = iframeHead.querySelector(`#${linkId}`);
                
                if (!existingLink) {
                    const link = document.createElement('link');
                    link.id = linkId;
                    link.href = `https://fonts.googleapis.com/css2?family=${fontName.replace(/\s+/g, '+')}:wght@400;500;600;700&display=swap`;
                    link.rel = 'stylesheet';
                    iframeHead.appendChild(link);
                }
            }
        });
    }
}

// Function to load navigation data from API
async function loadNavigationData() {
    try {
        const response = await fetch('/api/builder/navigation', {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json'
            }
        });
        
        if (!response.ok) {
            throw new Error('Failed to load navigation data');
        }
        
        currentNavigationData = await response.json();
        console.log('[DEBUG] Loaded navigation data:', currentNavigationData);
        
    } catch (error) {
        console.error('[ERROR] Failed to load navigation data:', error);
        currentNavigationData = [];
    }
}

// Function to save navigation data to API
async function saveNavigationData() {
    try {
        const response = await fetch('/api/builder/navigation', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(currentNavigationData)
        });
        
        if (!response.ok) {
            throw new Error('Failed to save navigation data');
        }
        
        console.log('[DEBUG] Navigation data saved successfully');
        return true;
        
    } catch (error) {
        console.error('[ERROR] Failed to save navigation data:', error);
        return false;
    }
}

// Function to save menus data
async function saveMenusData() {
    try {
        // For now, we'll save menus as part of the global theme settings
        // This ensures they persist with the website configuration
        if (!currentGlobalThemeSettings.menus) {
            currentGlobalThemeSettings.menus = {};
        }
        
        // Save all menus
        currentGlobalThemeSettings.menus = currentMenusData;
        
        // Mark that we have pending changes
        hasPendingGlobalSettingsChanges = true;
        
        // Save immediately
        const response = await fetch('/api/builder/websites/current/global-settings', {
            method: 'PUT',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                globalSettings: currentGlobalThemeSettings
            })
        });
        
        if (!response.ok && response.status !== 204) {
            throw new Error('Failed to save menus data');
        }
        
        console.log('[DEBUG] Menus data saved successfully');
        hasPendingGlobalSettingsChanges = false;
        return true;
        
    } catch (error) {
        console.error('[ERROR] Failed to save menus data:', error);
        return false;
    }
}

