                    // Make a deep copy of currentSectionsConfig for pagesConfig
                    const sectionsConfigForSave = JSON.parse(JSON.stringify(currentSectionsConfig));
                    const savedSectionOrder = sectionsConfigForSave.sectionOrder || [];
