    window.configureFooterBlock = function(blockId, blockType) {
        console.log('[DEBUG] Configuring footer block:', blockId, blockType);
        
        if (!currentSectionsConfig.footer?.blocks?.[blockId]) {
            console.error('[DEBUG] Footer block not found:', blockId);
            return;
        }
        
        // Ensure the block has the correct default structure
        const block = currentSectionsConfig.footer.blocks[blockId];
        if (!block.type) {
            block.type = blockType || 'text';
        }
        
        // Navigate to the appropriate settings view based on block type
        switch(block.type) {
            case 'logo-with-text':
            case 'logo':
                window.switchSidebarView('footerLogoWithTextSettings', { blockId });
                break;
            case 'subscribe':
            case 'newsletter':
                window.switchSidebarView('footerSubscribeSettings', { blockId });
                break;
            case 'menu':
                window.switchSidebarView('footerMenuSettings', { blockId });
                break;
            case 'text':
                window.switchSidebarView('footerTextSettings', { blockId });
                break;
            case 'social-media':
            case 'social':
                window.switchSidebarView('footerSocialMediaSettings', { blockId });
                break;
            default:
                console.error('[DEBUG] Unknown footer block type:', block.type);
        }
    };
    
    window.executeModuleFunction = function(moduleName, functionName, ...args) {
        console.log(`[MODULE] Executing ${moduleName}.${functionName}`, args);
        
        if (!window.WebsiteBuilderModules) {
            console.error('[MODULE] WebsiteBuilderModules not found');
            return null;
        }
        
        if (!window.WebsiteBuilderModules[moduleName]) {
            console.error(`[MODULE] Module ${moduleName} not found`);
            return null;
        }
        
        if (typeof window.WebsiteBuilderModules[moduleName][functionName] !== 'function') {
            console.error(`[MODULE] Function ${functionName} not found in module ${moduleName}`);
            console.log('[MODULE] Available functions:', Object.keys(window.WebsiteBuilderModules[moduleName]));
            return null;
        }
        
        try {
            const result = window.WebsiteBuilderModules[moduleName][functionName](...args);
            console.log(`[MODULE] ${moduleName}.${functionName} returned:`, result ? 'content' : 'null/undefined');
            return result;
        } catch (error) {
            console.error(`[MODULE] Error executing ${moduleName}.${functionName}:`, error);
            return null;
        }
    };
    
// ========== MODULAR SYSTEM LOADER - FUERA DE DOCUMENT READY ==========
// El sistema modular debe estar disponible ANTES de que los módulos intenten registrarse

console.log('[MODULE LOADER] Initializing modular system...');

window.WebsiteBuilderModules = window.WebsiteBuilderModules || {};
window.registeredModules = window.registeredModules || {};

// Create module view handler
window.moduleViewHandler = function(viewName, data) {
    console.log('[MODULE LOADER] Checking view:', viewName);
    console.log('[MODULE LOADER] Registered modules:', Object.keys(window.registeredModules));
    
    // Special case for accordionItemSettings
    if (viewName === 'accordionItemSettings') {
        console.log('[MODULE LOADER] Handling accordion item settings');
        const accordionModule = window.registeredModules['accordion'] || window.WebsiteBuilderModules?.Accordion;
        if (accordionModule && accordionModule.renderItemSettings) {
            // Update sidebar view tracking
            previousSidebarView = currentSidebarView;
            currentSidebarView = viewName;
            
            try {
                const itemId = data?.itemId || window.currentAccordionItemId;
                const html = accordionModule.renderItemSettings(itemId);
                $('#sidebar-dynamic-content').html(html);
                
                if (accordionModule.attachItemEventListeners) {
                    setTimeout(() => {
                        accordionModule.attachItemEventListeners(itemId);
                    }, 0);
                } else if (accordionModule.attachEventListeners) {
                    setTimeout(() => {
                        accordionModule.attachEventListeners();
                    }, 0);
                }
                
                // Apply translations if available
                if (typeof applyTranslations === 'function') {
                    setTimeout(applyTranslations, 0);
                }
                
                console.log(`[MODULE LOADER] Successfully loaded accordion item view`);
                return true;
            } catch (error) {
                console.error(`[MODULE LOADER] Error rendering accordion item:`, error);
                return false;
            }
        }
    }
    
    // Check if this is a module view
    for (const moduleName in window.registeredModules) {
        if (viewName === `${moduleName}Settings`) {
            console.log(`[MODULE LOADER] Found matching module: ${moduleName}`);
            const module = window.registeredModules[moduleName];
            
            // Update sidebar view tracking
            previousSidebarView = currentSidebarView;
            currentSidebarView = viewName;
            
            try {
                const html = module.renderSettings(data);
                $('#sidebar-dynamic-content').html(html);
                
                if (module.attachEventHandlers) {
                    setTimeout(() => {
                        module.attachEventHandlers();
                    }, 0);
                }
                
                // Apply translations if available
                if (typeof applyTranslations === 'function') {
                    setTimeout(applyTranslations, 0);
                }
                
                console.log(`[MODULE LOADER] Successfully loaded view: ${viewName}`);
                return true;
            } catch (error) {
                console.error(`[MODULE LOADER] Error rendering ${viewName}:`, error);
                return false;
            }
        }
    }
    console.log('[MODULE LOADER] No matching module found for:', viewName);
    return false;
};

// We'll override switchSidebarView after document ready
$(document).ready(function() {
    // Store the original switchSidebarView function
    if (!window.originalSwitchSidebarView && window.switchSidebarView) {
        window.originalSwitchSidebarView = window.switchSidebarView;
        console.log('[MODULE LOADER] Stored original switchSidebarView');
        
        // Override switchSidebarView to check modules first
        window.switchSidebarView = function(viewName, data) {
            console.log('[MODULE LOADER] switchSidebarView intercepted:', viewName);
            
            // Try module handler first
            if (window.moduleViewHandler(viewName, data)) {
                return;
            }
            
            // Fall back to original function
            console.log('[MODULE LOADER] Falling back to original switchSidebarView');
            return window.originalSwitchSidebarView.apply(this, arguments);
        };
    }
});

window.registerWebsiteBuilderModule = function(module) {
    if (!module || !module.config || !module.config.name) {
        console.error('[MODULE LOADER] Invalid module registration:', module);
        return false;
    }
    
    const moduleName = module.config.name;
    
    // Prevent duplicate registration
    if (window.registeredModules[moduleName]) {
        console.warn(`[MODULE LOADER] Module '${moduleName}' already registered`);
        return false;
    }
    
    // 1. Register translations when available
    if (module.config.displayName) {
        $(document).ready(function() {
            if (typeof translations !== 'undefined') {
                Object.keys(module.config.displayName).forEach(lang => {
                    if (translations[lang]) {
                        translations[lang][`sections.${moduleName}`] = module.config.displayName[lang];
                    }
                });
            }
        });
    }
    
    // 2. Register preview render function
    if (module.renderPreview) {
        window[`render${moduleName.charAt(0).toUpperCase() + moduleName.slice(1)}`] = function(settings) {
            return module.renderPreview(settings);
        };
    }
    
    // 3. Mark as registered
    window.registeredModules[moduleName] = module;
    
    console.log(`[MODULE LOADER] Successfully registered module: ${moduleName}`);
    return true;
};

// ========== FIN DEL LOADER ==========

// ========== SISTEMA DE CARRITO ==========
// Cart management system
let cartItems = [];

// Format price with thousands separator
function formatPrice(price) {
    return price.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

// Load cart from localStorage on page load
function loadCart() {
    const savedCart = localStorage.getItem('websiteBuilderCart');
    if (savedCart) {
        cartItems = JSON.parse(savedCart);
    }
    return cartItems;
}

// Save cart to localStorage
function saveCart() {
    localStorage.setItem('websiteBuilderCart', JSON.stringify(cartItems));
}

// Add to cart function - global para acceso desde los botones
window.addToCart = function(productId) {
    console.log('[CART] Adding product to cart:', productId);
    
    // Create product data (en producción esto vendría de una API o base de datos)
    const productData = {
        id: productId,
        name: `Producto ${productId.split('-')[1]}`,
        price: Math.floor(Math.random() * 100) + 10, // Precio aleatorio entre 10-110
        quantity: 1,
        image: '', // Placeholder por ahora
        vendor: 'Mi Tienda'
    };
    
    // Check if product already exists in cart
    const existingItemIndex = cartItems.findIndex(item => item.id === productId);
    
    if (existingItemIndex > -1) {
        // Increment quantity if already exists
        cartItems[existingItemIndex].quantity += 1;
    } else {
        // Add new item
        cartItems.push(productData);
    }
    
    // Save to localStorage
    saveCart();
    
    // Show cart drawer if we're in cart configuration view
    if (currentSidebarView === 'cartSettings') {
        // Find cart drawer in preview iframe and open it
        const previewIframe = document.getElementById('preview-iframe');
        if (previewIframe && previewIframe.contentWindow) {
            const iframeDoc = previewIframe.contentWindow.document;
            const drawers = iframeDoc.querySelectorAll('.cart-drawer');
            
            if (drawers.length > 0) {
                const drawer = drawers[0];
                const overlay = iframeDoc.getElementById(drawer.id + '-overlay');
                
                if (drawer && overlay) {
                    // Open drawer first
                    overlay.style.display = 'block';
                    setTimeout(() => {
                        drawer.style.right = '0';
                        // Update cart content after drawer is visible
                        setTimeout(() => {
                            updateCartDrawerContent(drawer.id);
                        }, 100);
                    }, 10);
                }
            }
        }
    }
    
    // Update cart icon count if exists
    updateCartIconCount();
    
    console.log('[CART] Cart updated:', cartItems);
};

// Update cart drawer content
// Function to handle checkout button click
window.handleCheckoutClick = function() {
    console.log('[CHECKOUT] handleCheckoutClick called');
    
    // Always redirect directly to checkout
    window.location.href = '/checkout';
    
    // Prevent any default behavior
    return false;
};

// Function to redirect iframe to checkout
window.redirectIframeToCheckout = function() {
    console.log('[CHECKOUT] Simulating checkout in editor');
    
    // In the editor context, show a message or open in new tab
    const userChoice = confirm('¿Deseas ver la página de checkout? Se abrirá en una nueva pestaña para no perder tu trabajo en el editor.');
    
    if (userChoice) {
        window.open('/checkout', '_blank');
    }
    
    // Close the drawer after action
    const previewIframe = document.getElementById('preview-iframe');
    if (previewIframe && previewIframe.contentWindow) {
        const iframeDoc = previewIframe.contentDocument;
        const drawers = iframeDoc.querySelectorAll('.cart-drawer');
        drawers.forEach(drawer => {
            const drawerId = drawer.id;
            if (previewIframe.contentWindow.closeCartDrawer) {
                previewIframe.contentWindow.closeCartDrawer(drawerId);
            }
        });
    }
    
    return false;
};

// Helper function to render drawer buttons based on showAs setting
function renderDrawerButtons(drawerId, trans) {
    // Get cart configuration
    const cartConfig = currentSectionsConfig.cart || {};
    const showAs = cartConfig.showAs || 'drawer';
    const drawerCheckoutText = cartConfig.drawerCheckoutButtonText || trans['cart.checkout'] || 'Checkout';
    const drawerViewCartText = cartConfig.drawerViewCartButtonText || trans['cart.viewCart'] || 'View cart';
    const drawerContinueShoppingText = cartConfig.drawerContinueShoppingText || trans['cart.continue.shopping'] || 'Continue shopping';
    
    console.log('[CART] Rendering drawer buttons for showAs:', showAs);
    
    let buttonsHtml = '';
    
    if (showAs === 'drawer') {
        // Only checkout button - redirect in iframe context
        buttonsHtml = `
            <button onclick="window.parent.redirectIframeToCheckout()" 
                    style="width: 100%; padding: 12px; background-color: #121212; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 14px; margin-bottom: 8px;">
                ${drawerCheckoutText}
            </button>
        `;
    } else if (showAs === 'drawer-and-page') {
        // Both view cart and checkout buttons
        buttonsHtml = `
            <button onclick="if(window.parent && window.parent !== window && window.parent.switchToPage) { window.parent.switchToPage('cart'); } else { window.location.href='/cart'; }" 
                    style="width: 100%; padding: 12px; background-color: transparent; color: #121212; border: 1px solid #121212; border-radius: 4px; cursor: pointer; font-size: 14px; margin-bottom: 8px;">
                ${drawerViewCartText}
            </button>
            <button onclick="window.parent.redirectIframeToCheckout()" 
                    style="width: 100%; padding: 12px; background-color: #121212; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 14px; margin-bottom: 8px;">
                ${drawerCheckoutText}
            </button>
        `;
    }
    
    // Always add continue shopping button
    buttonsHtml += `
        <button onclick="if(window.parent && window.parent.closeCartDrawer) { window.parent.closeCartDrawer('${drawerId}'); }" 
                style="width: 100%; padding: 12px; background-color: transparent; color: #121212; border: 1px solid #121212; border-radius: 4px; cursor: pointer; font-size: 14px;">
            ${drawerContinueShoppingText}
        </button>
    `;
    
    return buttonsHtml;
}

function updateCartDrawerContent(drawerId) {
    console.log('[CART] Updating drawer content for:', drawerId);
    
    const previewIframe = document.getElementById('preview-iframe');
    if (!previewIframe || !previewIframe.contentWindow) {
        console.log('[CART] Preview iframe not found');
        return;
    }
    
    const iframeDoc = previewIframe.contentWindow.document;
    const drawer = iframeDoc.getElementById(drawerId);
    if (!drawer) {
        console.log('[CART] Drawer not found:', drawerId);
        return;
    }
    
    const cartContent = drawer.querySelector('.cart-drawer-content');
    if (!cartContent) {
        console.log('[CART] Cart content element not found');
        return;
    }
    
    // Load current cart
    loadCart();
    console.log('[CART] Cart items loaded:', cartItems.length, cartItems);
    
    // Get translations from parent window
    const trans = translations[currentLanguage] || translations['es'] || {};
    
    if (cartItems.length === 0) {
        // Show empty cart message
        cartContent.innerHTML = `
            <div style="text-align: center; padding: 40px 20px;">
                <p style="margin-bottom: 24px;">${trans['cart.empty.message'] || 'Your cart is currently empty.'}</p>
                <button onclick="if(window.parent && window.parent.closeCartDrawer) { window.parent.closeCartDrawer('${drawerId}'); }" 
                        style="padding: 12px 24px; background-color: #121212; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 14px;">
                    ${trans['cart.continue.shopping'] || 'Continue shopping'}
                </button>
            </div>
        `;
    } else {
        // Show cart items
        let cartItemsHtml = cartItems.map(item => `
            <div style="display: flex; gap: 16px; padding: 16px 20px; border-bottom: 1px solid #e5e5e5;">
                ${item.image ? `
                    <img src="${item.image}" alt="${item.name}" style="width: 80px; height: 80px; object-fit: cover; border-radius: 4px; flex-shrink: 0;">
                ` : `
                    <div style="width: 80px; height: 80px; background-color: #f0f0f0; border-radius: 4px; flex-shrink: 0; display: flex; align-items: center; justify-content: center;">
                        <span class="material-symbols-outlined" style="font-size: 32px; color: #ccc;">image</span>
                    </div>
                `}
                <div style="flex: 1; padding-left: 8px;">
                    <h4 style="margin: 0 0 4px 0; font-size: 14px; font-weight: 500;">${item.name}</h4>
                    <p style="margin: 0 0 8px 0; font-size: 12px; color: #666;">${item.vendor}</p>
                    <div style="display: flex; align-items: center; gap: 12px;">
                        <div style="display: flex; align-items: center; border: 1px solid #e5e5e5; border-radius: 4px;">
                            <button onclick="window.parent.updateCartQuantity('${item.id}', ${item.quantity - 1})" 
                                    style="width: 32px; height: 32px; border: none; background: none; cursor: pointer;">-</button>
                            <span style="padding: 0 12px; font-size: 14px;">${item.quantity}</span>
                            <button onclick="window.parent.updateCartQuantity('${item.id}', ${item.quantity + 1})" 
                                    style="width: 32px; height: 32px; border: none; background: none; cursor: pointer;">+</button>
                        </div>
                        <span style="font-size: 14px; font-weight: 500;">$${formatPrice(item.price * item.quantity)}</span>
                    </div>
                </div>
                <button onclick="window.parent.removeFromCart('${item.id}')" 
                        style="width: 24px; height: 24px; border: none; background: none; cursor: pointer; padding: 0; margin-left: 8px;">
                    <span class="material-symbols-outlined" style="font-size: 20px;">close</span>
                </button>
            </div>
        `).join('');
        
        const subtotal = cartItems.reduce((total, item) => total + (item.price * item.quantity), 0);
        
        cartContent.innerHTML = `
            <div style="max-height: calc(100vh - 200px); overflow-y: auto;">
                ${cartItemsHtml}
            </div>
            <div style="padding: 20px; border-top: 1px solid #e5e5e5;">
                <div style="display: flex; justify-content: space-between; margin-bottom: 16px;">
                    <span style="font-size: 16px; font-weight: 500;">${trans['cart.subtotal'] || 'Subtotal'}</span>
                    <span style="font-size: 16px; font-weight: 500;">$${formatPrice(subtotal)}</span>
                </div>
                ${renderDrawerButtons(drawerId, trans)}
            </div>
        `;
    }
}

// Update cart quantity
window.updateCartQuantity = function(productId, newQuantity) {
    console.log('[CART] Updating quantity for:', productId, 'to:', newQuantity);
    if (newQuantity <= 0) {
        window.removeFromCart(productId);
        return;
    }
    
    // Convertir productId a string para comparación consistente
    const productIdStr = String(productId);
    const itemIndex = cartItems.findIndex(item => String(item.id) === productIdStr);
    if (itemIndex > -1) {
        cartItems[itemIndex].quantity = newQuantity;
        saveCart();
        
        // Update drawer content
        const previewIframe = document.getElementById('preview-iframe');
        if (previewIframe && previewIframe.contentWindow) {
            const iframeDoc = previewIframe.contentWindow.document;
            const drawers = iframeDoc.querySelectorAll('.cart-drawer');
            if (drawers.length > 0) {
                updateCartDrawerContent(drawers[0].id);
            }
        }
    }
};

